// what a step gives the student to read (for the Knowledge Archive), and every knowledge scroll of an episode
export const stepIds = (s) => [
  ...(s.ids ?? []), ...(s.do === 'route' ? s.stops.map((x) => x.src) : []), ...(s.do === 'journey' ? s.src : []),
  ...(s.do === 'lanterns' ? s.people.map((x) => x.src) : []),
];
export const scrollIds = (ep) => ep.steps.flatMap((s) => (['scrolls'].includes(s.do) ? s.items : ['parkour', 'smash', 'vault'].includes(s.do) ? s.scrolls ?? [] : []).map((x) => x.src));

